Actually let me have readTagFile do format validation and output the 32 bytes, returning status. Cleaner:

```cpp
// The outcome of sourcing the expected tag from a tag file.
enum class TagFileStatus { kOk, kReadError, kFormatError };

// Read and validate a tag file: exactly 64 hexadecimal characters
// denoting the 32-byte tag, either ending right there or followed by a
// single LF or CRLF line ending. ...
TagFileStatus readTagFile(const std::string& path,
                          std::vector<unsigned char>& tag) {
    // The path is always a plain file name: a lone "-" is NOT standard
    // input here (unlike --file).
    std::ifstream in(path, std::ios::binary | std::ios::in);
    if (!in) {
        return TagFileStatus::kReadError;
    }
    // The file is tiny (at most 66 valid bytes), so reading it whole is
    // fine. If any read fails partway, badbit is set and the partial
    // content is discarded: a prefix that happens to look like a complete
    // tag must never be verified against.
    std::string content((std::istreambuf_iterator<char>(in)),
                        std::istreambuf_iterator<char>());
    if (in.bad()) {
        return TagFileStatus::kReadError;
    }
    std::string_view hex(content);
    if (hex.size() >= 2 && hex.compare(hex.size() - 2, 2, "\r\n") == 0) {
        hex.remove_suffix(2);
    } else if (!hex.empty() && hex.back() == '\n') {
        hex.remove_suffix(1);
    }
    if (hex.size() != 2 * kTagBytes || !decodeHex(hex, tag) ||
        tag.size() != kTagBytes) {
        return TagFileStatus::kFormatError;
    }
    return TagFileStatus::kOk;
}
```

